window.renderMathInElement=window.renderMathInElement||function(root,opts){var d=opts.delimiters||[];function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}function walk(n){if(n.nodeType===3){var t=n.nodeValue;d.forEach(function(x){var r=new RegExp(esc(x.left)+"([\\s\\S]+?)"+esc(x.right),"g");t=t.replace(r,function(_,m){return x.display?"\\n"+m+"\\n":m})});n.nodeValue=t}else if(n.nodeType===1&&!/^(script|style|textarea|pre|code)$/i.test(n.tagName)){Array.prototype.slice.call(n.childNodes).forEach(walk)}}walk(root)};

